-- Migration 424: AA-1096 (lane l5, tech lead S279: "env vars stay for one release as an emergency override, then go")
-- -- the one-release env overrides of the platform settings registry are retired.
--
-- Why. CIS 407 / 411 / 412 / 418 gave 25 definitions an env_override (the old env switch of the value, kept for one
-- release so an operator could still pin it by hand): cis.erasure.tenant_retention_days (ERASURE_TENANT_RETENTION_DAYS),
-- 21 cis.quality_modes.* keys (T10_* / T10_SA_MODE* / T10_ADJ_MODE* / T7_DEBATE_MODE / T9_BRIEF_GROUNDING_MODE),
-- cis.t7.blog_chars_per_seed_word (T7_BLOG_CHARS_PER_SEED_WORD) and cis.t9.blog_length_extend (T9_LENGTH_EXTEND). The
-- release has passed (S279 settings shipped, S280 deployed again) and no task definition sets any of them any more
-- (AA-CIS-Infra lane L6 removed them). While a definition names an env var, a stray value on a task silently wins over
-- the value the administrator approved; the page is the one place to change these values now.
--
-- What.
--   1. The block between "settings-edit:begin" and "settings-edit:end" (read by scripts/settings/gen_compiled_defaults.py
--      into shared/settings/compiled_defaults.json, the file the reader and the admin API serve; the seed-parity test
--      keeps the two equal): for the 25 keys, env_override null and the description and EN / VI guide without the
--      "emergency override for one release" sentence (the erasure key: the Dev drill now sets the value here); for 14
--      TripPlanner keys (CIS 414), the description and guide without the TripPlanner env fallback (AA-TripPlanner-Web
--      drops those env reads in the same wave: the fallback is the code default, equal to this default).
--   2. A post-check: every row of the block is in force, and no definition of the table names an env var any more.
--   3. Register 424.
--
-- Behaviour on apply. None for running code: the reader and the admin API serve the compiled defaults (regenerated
-- from this block in the same PR), not this table's env_override column; no value, bound, approval rule or enforcement
-- flag changes. The env_override mechanism itself stays (a future definition may carry one for one release:
-- tests/unit/test_aa1096_settings_env_lint.py lists it with its removal date and fails once that date has passed).
--
-- Class: CONTRACT (root ADR 0017 decision 3; no migrate directive line): UPDATEs of existing config rows and one DO
-- block (the post-check). No readiness raise. MIG-4 deviation (recorded in the implementation notes): this file ships
-- in ONE PR with the code that stops naming the retired env vars, not as a migration-only PR, because the seed-parity
-- and migration-replay tests bind this block, the generator and compiled_defaults.json together (either half alone is
-- red), and no code reads the column, so a deploy before the apply changes nothing. On Dev, Infra Migration Apply
-- once every job table is idle (root ADR 0017a). DM-6.1: no personal data (definition text). DM-7.1: no new table.
--
-- Number. 420 is the newest CIS migration on main (15/11/2026) and 421-423 are taken by other lanes of this wave. If
-- the owner main max + 1 differs at merge, renumber (git grep '424_' and '424' here, in
-- tests/integration/test_aa1096_migration_424.py, compiled_defaults.json's _generated line and the implementation
-- notes docs/implementation-notes/AA-1096-l5-settings-env.md).
--
-- Locks. UPDATEs of 39 rows of a ~220-row table read by no hot path (the reader reads shared.setting_value); the
-- definition guard trigger (CIS 407) allows the file's role, cis_owner. lock_timeout 5s. Re-runnable (the Integration
-- Tests replay every file): the UPDATE skips equal rows.
--
-- Rollback (a new forward migration): put env_override, description and guide back for the keys from CIS 407 / 411 /
-- 412 / 414 / 416 / 418 (only to re-open an emergency override; the code needs no change).

BEGIN;
SET LOCAL lock_timeout = '5s';

-- settings-edit:begin (scripts/settings/gen_compiled_defaults.py reads the JSON array of the dollar-quoted block)
CREATE TEMP TABLE IF NOT EXISTS m428_edit (key text PRIMARY KEY, doc jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO m428_edit (key, doc)
SELECT e.doc ->> 'key', e.doc
  FROM jsonb_array_elements($edit$[
{"key": "cis.erasure.tenant_retention_days", "env_override": null, "description": "Days after a tenant's offboarding before the data erasure may remove its CIS data (the apply switch itself stays in Terraform). The Dev erasure drill sets 0 here for its run and puts the value back after it."},
{"key": "cis.quality_modes.t10_adjudicate", "env_override": null, "description": "off: no call. shadow: the judge's verdicts are recorded only. repair: a violation gets one sentence repair, never a hold (paid judge calls once on). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "A paid AI judge that takes a second look at four kinds of findings of the free checks (a leaked naming note, a repeat in other words, a FAQ answer that does not answer, a superlative with no scope) and decides whether they are real. This sets the mode of every kind whose own setting is inherit. off: no call. shadow: its verdicts are recorded only. repair: a confirmed finding gets one sentence repair, never a hold.", "raise": "repair (the stricter choice): confirmed findings are repaired; paid judge calls start.", "lower": "off or shadow (the looser choices): no repair; off makes no paid call, shadow pays for calls to measure the judge.", "when": "Use shadow to measure the judge before trusting it, then repair when its verdicts prove right. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default off: no second-opinion call is made."}, "vi": {"what": "Một giám khảo AI có phí xem lại bốn kiểu phát hiện của các bước kiểm miễn phí (lộ ghi chú cách gọi tên, lặp ý bằng lời khác, câu trả lời FAQ lạc đề, khen tột bậc không phạm vi) và quyết định có đúng là lỗi không. Thiết lập này đặt chế độ cho mọi kiểu có thiết lập riêng là inherit. off: không gọi. shadow: chỉ ghi lại kết luận. repair: phát hiện được xác nhận sẽ được sửa một câu, không giữ bài.", "raise": "repair (lựa chọn chặt hơn): phát hiện được xác nhận sẽ được sửa; bắt đầu có lượt gọi giám khảo có phí.", "lower": "off hoặc shadow (lựa chọn nới hơn): không sửa; off không gọi có phí, shadow trả phí để đo giám khảo.", "when": "Dùng shadow để đo giám khảo trước khi tin, rồi chuyển sang repair khi kết luận được chứng minh đúng. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định off: không có lượt gọi xem lại nào."}}},
{"key": "cis.quality_modes.t10_adjudicate_faq_non_answer", "env_override": null, "description": "Mode of the tier-2 adjudicator class faq_non_answer; inherit = the mode of every class above. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "The mode for one kind of finding, a FAQ answer that does not answer its question. inherit = follow the second-opinion judge setting for every kind; or pick off, shadow or repair for this kind alone.", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, câu trả lời FAQ không trả lời đúng câu hỏi. inherit = theo thiết lập chung của nhóm (giám khảo xem lại); hoặc chọn off, shadow or repair cho riêng kiểu này.", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_adjudicate_naming_note_leak", "env_override": null, "description": "Mode of the tier-2 adjudicator class naming_note_leak; inherit = the mode of every class above. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "The mode for one kind of finding, a naming note (how to spell or call a place) that leaked into the text. inherit = follow the second-opinion judge setting for every kind; or pick off, shadow or repair for this kind alone.", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, ghi chú về cách viết hay cách gọi tên địa danh lọt vào bài. inherit = theo thiết lập chung của nhóm (giám khảo xem lại); hoặc chọn off, shadow or repair cho riêng kiểu này.", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_adjudicate_paraphrased_repeat", "env_override": null, "description": "Mode of the tier-2 adjudicator class paraphrased_repeat; inherit = the mode of every class above. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "The mode for one kind of finding, the same point said twice in different words. inherit = follow the second-opinion judge setting for every kind; or pick off, shadow or repair for this kind alone.", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, cùng một ý được nói hai lần bằng lời khác nhau. inherit = theo thiết lập chung của nhóm (giám khảo xem lại); hoặc chọn off, shadow or repair cho riêng kiểu này.", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_adjudicate_scopeless_superlative", "env_override": null, "description": "Mode of the tier-2 adjudicator class scopeless_superlative; inherit = the mode of every class above. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "The mode for one kind of finding, a superlative with no scope (the best, the most beautiful) that the source does not support. inherit = follow the second-opinion judge setting for every kind; or pick off, shadow or repair for this kind alone.", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, lời khen tột bậc không nêu phạm vi (đẹp nhất, tuyệt nhất) mà nguồn không chứng minh. inherit = theo thiết lập chung của nhóm (giám khảo xem lại); hoặc chọn off, shadow or repair cho riêng kiểu này.", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_f12_scope", "env_override": null, "description": "warn: a place outside the piece's scope is reported only. block: a body finding blocks for one sentence repair and holds the piece when it is left (AA-788). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "What the free scope check does when a blog or social post names a place outside the piece's scope (a place no day of the trip visits). warn: reported only. block: a finding in the body gets one sentence repair, and the piece is held if it is still there.", "raise": "block (the stricter choice): pieces stop naming places the trip does not visit; more repairs (paid) and holds.", "lower": "warn (the looser choice): the piece goes on with a flag.", "when": "Choose block when tenants receive pieces that send readers to places the tour never visits. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default warn: out-of-scope places are flagged, nothing is held."}, "vi": {"what": "Bước kiểm phạm vi (miễn phí) xử lý ra sao khi bài blog hay mạng xã hội nêu một địa điểm ngoài phạm vi của bài (nơi không ngày nào của chuyến ghé). warn: chỉ báo. block: lỗi trong thân bài được sửa một câu, nếu vẫn còn thì bài bị giữ.", "raise": "block (lựa chọn chặt hơn): bài không còn nhắc nơi chuyến đi không ghé; nhiều lần sửa (có phí) và giữ bài hơn.", "lower": "warn (lựa chọn nới hơn): bài đi tiếp kèm cờ.", "when": "Chọn block khi đại lý nhận bài dẫn người đọc tới nơi tour không hề ghé. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định warn: địa điểm ngoài phạm vi được gắn cờ, không giữ bài."}}},
{"key": "cis.quality_modes.t10_f14_floor", "env_override": null, "description": "repair: a social piece under its length floor gets the attempt-1 rewrite (AA-780). warn: the kill switch, reported only. Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "What happens when a social post comes out shorter than its channel's minimum. repair: the post is rewritten once (a paid call). warn: reported only, the switch to stop those rewrites.", "raise": "repair (the stricter choice): short posts are lengthened once before delivery; one more paid call each.", "lower": "warn (the looser choice): short posts go out as written, with a flag.", "when": "Choose warn if the rewrites misbehave (for example they add facts) or cost too much; repair otherwise. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default repair: a too-short post is rewritten once."}, "vi": {"what": "Xử lý ra sao khi bài mạng xã hội ngắn hơn mức tối thiểu của kênh. repair: viết lại bài một lần (lượt gọi có phí). warn: chỉ báo, là công tắc để dừng các lần viết lại đó.", "raise": "repair (lựa chọn chặt hơn): bài quá ngắn được kéo dài một lần trước khi giao; thêm một lượt gọi có phí mỗi bài.", "lower": "warn (lựa chọn nới hơn): bài ngắn được giao nguyên trạng, kèm cờ.", "when": "Chọn warn nếu lần viết lại hoạt động sai (ví dụ thêm dữ kiện) hoặc quá tốn; còn lại để repair. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định repair: bài quá ngắn được viết lại một lần."}}},
{"key": "cis.quality_modes.t10_f9_brand_style", "env_override": null, "description": "warn: off-brand wording is reported only. repair: on attempt 1 a flagged body sentence gets one sentence repair (never a hold) (AA-788). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "What happens when the AI judge finds off-brand or AI-sounding wording in a blog or social post. warn: reported only. repair: on the first attempt, a flagged sentence gets one sentence repair (never a hold).", "raise": "repair (the stricter choice): flagged sentences are rewritten once; one more paid call per flagged piece.", "lower": "warn (the looser choice): the wording stays, staff see a flag.", "when": "Choose repair when tenants keep editing out wording the judge already flagged. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default warn: flagged wording is listed, not changed."}, "vi": {"what": "Xử lý ra sao khi giám khảo AI thấy câu chữ lệch thương hiệu hoặc nghe như máy viết trong bài blog hay mạng xã hội. warn: chỉ báo. repair: ở lần viết đầu, câu bị gắn cờ được sửa một lần (không bao giờ giữ bài).", "raise": "repair (lựa chọn chặt hơn): câu bị gắn cờ được viết lại một lần; thêm một lượt gọi có phí mỗi bài bị gắn cờ.", "lower": "warn (lựa chọn nới hơn): câu chữ giữ nguyên, nhân viên thấy cờ.", "when": "Chọn repair khi đại lý liên tục tự sửa những câu giám khảo đã gắn cờ. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định warn: câu bị gắn cờ được liệt kê, không bị sửa."}}},
{"key": "cis.quality_modes.t10_f9_policy", "env_override": null, "description": "interim: only a trip promise holds, every other F9 class warns (the claim verdicts below). legacy: the pre-W0 verdict (rollback). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "Which policy the AI claim judge of blog and social posts follows. interim: only a trip promise the source lacks holds a piece; every other kind of finding follows its own claim setting on this page (warn by default). legacy: the older rule in which most findings held the piece, kept as a rollback.", "raise": "legacy (the stricter choice): far more pieces are held, including for claims the writing policy allows.", "lower": "interim (the looser choice): only trip promises hold; the rest are flags.", "when": "Switch to legacy only to roll back if the interim policy lets harmful claims through, or briefly to compare. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default interim: a blog that promises a sunrise view the source lacks is held; place background only gets a flag."}, "vi": {"what": "Giám khảo khẳng định (AI) của bài blog và mạng xã hội theo chính sách nào. interim: chỉ lời hứa chuyến đi không có trong nguồn mới giữ bài; các loại phát hiện khác theo thiết lập khẳng định riêng trên trang này (mặc định warn). legacy: quy tắc cũ, hầu hết phát hiện đều giữ bài, giữ lại để quay về khi cần.", "raise": "legacy (lựa chọn chặt hơn): nhiều bài bị giữ hơn hẳn, kể cả vì khẳng định chính sách viết cho phép.", "lower": "interim (lựa chọn nới hơn): chỉ lời hứa chuyến đi giữ bài; còn lại là cờ.", "when": "Chỉ chuyển sang legacy để quay về nếu chính sách interim để lọt khẳng định có hại, hoặc tạm thời để so sánh. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định interim: bài blog hứa cảnh bình minh mà nguồn không có sẽ bị giữ; bối cảnh địa danh chỉ bị gắn cờ."}}},
{"key": "cis.quality_modes.t10_seed_align", "env_override": null, "description": "off: the checks do not run. shadow: recorded only. repair: a finding gets one sentence repair, never a hold. hold: like repair, and a promoted fact class may hold (until a class is promoted, hold reads as repair) (AA-789). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "Free checks that compare a blog or social post with its source material and flag ten kinds of drift (an optional activity written as planned, 'near' written as 'at', a leaked brief line ...). This sets the mode of every kind whose own setting is inherit. off: they do not run. shadow: findings are recorded only. repair: a finding gets one sentence repair, never a hold. hold: like repair, and a kind promoted to a fact error may hold the piece.", "raise": "repair or hold (the stricter choices): drift from the source is repaired (a paid call per finding) and, on hold, may stop a piece.", "lower": "off or shadow (the looser choices): no repair; shadow still records what would have been found.", "when": "Move to shadow to measure the checks on real pieces, then to repair when their findings prove right. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default off: the checks do not run."}, "vi": {"what": "Các bước kiểm miễn phí so bài blog hay mạng xã hội với tư liệu nguồn và gắn cờ mười kiểu lệch (hoạt động tuỳ chọn viết như đã lên lịch, 'gần' viết thành 'tại', lộ câu của brief ...). Thiết lập này đặt chế độ cho mọi kiểu có thiết lập riêng là inherit. off: không chạy. shadow: chỉ ghi lại. repair: mỗi phát hiện được sửa một câu, không giữ bài. hold: như repair, và kiểu đã được nâng thành lỗi dữ kiện có thể giữ bài.", "raise": "repair hoặc hold (lựa chọn chặt hơn): phần lệch khỏi nguồn được sửa (mỗi phát hiện một lượt gọi có phí) và, ở hold, có thể chặn bài.", "lower": "off hoặc shadow (lựa chọn nới hơn): không sửa; shadow vẫn ghi lại những gì lẽ ra đã phát hiện.", "when": "Chuyển sang shadow để đo các bước kiểm trên bài thật, rồi sang repair khi kết quả được chứng minh đúng. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định off: các bước kiểm không chạy."}}},
{"key": "cis.quality_modes.t10_seed_align_brief_recipe_leak", "env_override": null, "description": "Mode of the seed-align class brief_recipe_leak; inherit = the mode of every class above (AA-789). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "The mode for one kind of finding, wording of the writing brief that leaked into the text. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone.", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, câu chữ của brief viết lọt vào bài. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này.", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_difficulty_promise", "env_override": null, "description": "Mode of the seed-align class difficulty_promise; inherit = the mode of every class above (AA-789). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "The mode for one kind of finding, a promise about how easy or hard the trip is that the source does not make. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone.", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, lời hứa về độ dễ hay khó của chuyến đi mà nguồn không nêu. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này.", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_naming_note_leak", "env_override": null, "description": "Mode of the seed-align class naming_note_leak; inherit = the mode of every class above (AA-789). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "The mode for one kind of finding, a naming note (how to spell or call a place) that leaked into the text. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone.", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, ghi chú về cách viết hay cách gọi tên địa danh lọt vào bài. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này.", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_near_as_at", "env_override": null, "description": "Mode of the seed-align class near_as_at; inherit = the mode of every class above (AA-789). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "The mode for one kind of finding, a stay or visit near a place written as being at the place. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone.", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, nơi ở hay điểm ghé gần một địa danh bị viết thành nằm tại địa danh đó. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này.", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_optional_as_planned", "env_override": null, "description": "Mode of the seed-align class optional_as_planned; inherit = the mode of every class above (AA-789). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "The mode for one kind of finding, an optional activity written as if it is part of the plan. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone.", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, hoạt động tuỳ chọn được viết như thể nằm trong kế hoạch. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này.", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_orphan_opener", "env_override": null, "description": "Mode of the seed-align class orphan_opener; inherit = the mode of every class above (AA-789). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "The mode for one kind of finding, an opening line that refers to something never introduced. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone.", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, câu mở đầu nhắc tới điều chưa từng được giới thiệu. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này.", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_paraphrased_repeat", "env_override": null, "description": "Mode of the seed-align class paraphrased_repeat; inherit = the mode of every class above (AA-789). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "The mode for one kind of finding, the same point said twice in different words. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone.", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, cùng một ý được nói hai lần bằng lời khác nhau. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này.", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_planned_as_optional", "env_override": null, "description": "Mode of the seed-align class planned_as_optional; inherit = the mode of every class above (AA-789). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "The mode for one kind of finding, a planned activity written as if it were optional. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone.", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, hoạt động có trong kế hoạch lại được viết như thể tuỳ chọn. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này.", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_scopeless_superlative", "env_override": null, "description": "Mode of the seed-align class scopeless_superlative; inherit = the mode of every class above (AA-789). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "The mode for one kind of finding, a superlative with no scope (the best, the most beautiful) that the source does not support. inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone.", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, lời khen tột bậc không nêu phạm vi (đẹp nhất, tuyệt nhất) mà nguồn không chứng minh. inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này.", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t10_seed_align_world_share_unsupported", "env_override": null, "description": "Mode of the seed-align class world_share_unsupported; inherit = the mode of every class above (AA-789). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "The mode for one kind of finding, a world-ranking or share-of-the-world claim the source does not support (home to half the world's ...). inherit = follow the source match checks setting for every kind; or pick off, shadow, repair or hold for this kind alone.", "raise": "A stricter mode than the family setting for this kind alone (for example repair while the rest stay on shadow): this drift gets repaired, at a paid call per finding.", "lower": "A looser mode for this kind alone (off or shadow): this kind stops being repaired while the others are.", "when": "Set it when one kind proves reliable (or noisy) before the others. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default inherit: this kind does what the family setting says."}, "vi": {"what": "Chế độ cho riêng một kiểu phát hiện, khẳng định xếp hạng thế giới hay tỷ lệ của thế giới mà nguồn không chứng minh (nơi có một nửa số ... của thế giới). inherit = theo thiết lập chung của nhóm (kiểm khớp nguồn); hoặc chọn off, shadow, repair or hold cho riêng kiểu này.", "raise": "Chế độ chặt hơn thiết lập chung cho riêng kiểu này (ví dụ repair khi các kiểu khác vẫn shadow): kiểu lệch này được sửa, mỗi phát hiện một lượt gọi có phí.", "lower": "Chế độ nới hơn cho riêng kiểu này (off hoặc shadow): kiểu này thôi được sửa trong khi các kiểu khác vẫn sửa.", "when": "Đặt khi một kiểu tỏ ra đáng tin (hoặc hay báo nhầm) sớm hơn các kiểu khác. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định inherit: kiểu này làm theo thiết lập chung của nhóm."}}},
{"key": "cis.quality_modes.t7_debate", "env_override": null, "description": "rank: flagged Slate candidates are ordered after unflagged ones, none dropped (AA-1079). cut: flagged candidates are cut, worst first, up to the cut fraction below (AA-631). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "When topics are proposed for a channel, a topic whose keyword is too contested (see the contested threshold) is flagged. rank: flagged topics are listed after the others, none dropped. cut: flagged topics are dropped, worst first, up to the cut share.", "raise": "cut (the stricter choice): fewer contested topics are proposed; a channel's list gets shorter.", "lower": "rank (the looser choice): every topic stays on the list; contested ones come last.", "when": "Choose cut when tenants keep getting topics they cannot rank for. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default rank: contested topics stay, at the end of the list."}, "vi": {"what": "Khi đề xuất chủ đề cho một kênh, chủ đề có từ khoá quá cạnh tranh (xem ngưỡng cạnh tranh) bị gắn cờ. rank: chủ đề bị gắn cờ xếp sau các chủ đề khác, không bỏ cái nào. cut: chủ đề bị gắn cờ bị loại, tệ nhất trước, tới tỷ lệ loại tối đa.", "raise": "cut (lựa chọn chặt hơn): ít chủ đề cạnh tranh được đề xuất hơn; danh sách của kênh ngắn lại.", "lower": "rank (lựa chọn nới hơn): mọi chủ đề vẫn trong danh sách; chủ đề cạnh tranh nằm cuối.", "when": "Chọn cut khi đại lý liên tục nhận chủ đề khó lên thứ hạng tìm kiếm. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định rank: chủ đề cạnh tranh vẫn còn, ở cuối danh sách."}}},
{"key": "cis.quality_modes.t9_brief_grounding", "env_override": null, "description": "off: the angle brief goes to the writer as written. r9: clauses of the brief the seed does not support are dropped before the writer sees it (AA-1049 R9). Evidence required: an eval or golden-set run id, or a $0 replay of stored pieces that shows the new verdicts.", "guide": {"en": {"what": "Before the blog and social writer sees its angle brief, the brief can be checked against the source. off: the brief goes to the writer as written. r9: lines of the brief the source does not support are dropped first, so the writer is not asked to write them.", "raise": "r9 (the stricter choice): fewer invented details reach the writer; a brief may lose a line it needed.", "lower": "off (the looser choice): the writer gets the whole brief, unsupported lines included.", "when": "Choose r9 when held pieces trace back to a brief that asked for something the source lacks. The change form asks for evidence: an evaluation run on a fixed set of reviewed pieces, or a free replay of stored pieces that shows the new verdicts.", "example": "With the default off: the brief goes to the writer unchanged."}, "vi": {"what": "Trước khi bộ viết blog và mạng xã hội nhận brief góc nhìn, brief có thể được đối chiếu với nguồn. off: brief được giao nguyên văn. r9: các dòng của brief mà nguồn không chứng minh bị bỏ trước, để bộ viết không bị yêu cầu viết chúng.", "raise": "r9 (lựa chọn chặt hơn): ít chi tiết bịa đến tay bộ viết hơn; brief có thể mất một dòng cần thiết.", "lower": "off (lựa chọn nới hơn): bộ viết nhận toàn bộ brief, kể cả dòng không có căn cứ.", "when": "Chọn r9 khi các bài bị giữ đều bắt nguồn từ brief yêu cầu điều nguồn không có. Form đổi giá trị yêu cầu bằng chứng: một lần chạy đánh giá trên một bộ bài đã được duyệt cố định, hoặc một lần replay miễn phí các bài đã lưu cho thấy kết quả mới.", "example": "Với mặc định off: brief được giao cho bộ viết nguyên vẹn."}}},
{"key": "cis.t7.blog_chars_per_seed_word", "env_override": null},
{"key": "cis.t9.blog_length_extend", "env_override": null, "description": "off: a blog still under the length minimum after its repair round is held for length (the full rewrite path, unchanged). on: a blog under the minimum after its repair round gets one lengthening repair first: one new paragraph in each of up to three of its thinnest sections, written only from facts of its own source that the blog does not use yet; each paragraph is checked in code (no new number, time, heading, list, question or call to action, no mention of where a fact comes from) and then every quality check runs again on the whole text. A tenant value turns it on for one agency only (a trial on an audit tenant); the platform value for everyone. Evidence required: a $0 replay of stored pieces, or a trial run whose cost is read from the call ledger."},
{"key": "tripplanner.ai.narration_cache_ttl_hours", "description": "Hours a narration in tripplanner.narration_cache is reused for the same itinerary before a new one is written (a longer window means fewer paid narrations). Fallback while TripPlanner cannot read the view: this default.", "guide": {"en": {"what": "How long a written trip story is reused for the same itinerary before a new one is written. A reused story costs nothing. If TripPlanner cannot read the settings, it uses this default.", "raise": "Fewer paid stories; a traveller may see an older story after the itinerary text was improved.", "lower": "Stories are rewritten more often: fresher wording, more paid calls.", "when": "Lower it right after the trip text or the story prompt changes, so travellers see the new version sooner; raise it to cut cost.", "example": "With the default of 168 hours (7 days): the same itinerary gets the same story for a week."}, "vi": {"what": "Một câu chuyện chuyến đi đã viết được dùng lại cho cùng lịch trình trong bao lâu trước khi viết câu chuyện mới. Dùng lại thì không tốn phí. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị mặc định này.", "raise": "Ít câu chuyện có phí hơn; khách có thể thấy câu chuyện cũ sau khi nội dung lịch trình đã được cải thiện.", "lower": "Câu chuyện được viết lại thường hơn: lời văn mới hơn, nhiều lượt gọi có phí hơn.", "when": "Giảm ngay sau khi nội dung chuyến đi hay prompt kể chuyện thay đổi, để khách sớm thấy bản mới; tăng để giảm chi phí.", "example": "Với mặc định 168 giờ (7 ngày): cùng một lịch trình nhận cùng một câu chuyện trong một tuần."}}},
{"key": "tripplanner.handoff.advisor_demo", "description": "On (the B2B-only model, root ADR 0019): on the bare planner and the AA demo tenant, send to advisor answers 410 b2b_only before any write (no registration, no inquiry, no Booking case). An agency tenant's planner sends leads to that tenant either way. Off turns the frozen AA hand-off back on. Fallback while TripPlanner cannot read the view: this default.", "guide": {"en": {"what": "On (business-to-business only): on the bare planner and the AA demo, 'send to advisor' answers that the service is for agencies and stores nothing (no registration, no enquiry, no Booking case). An agency's planner sends leads to that agency either way. Off turns the old AA hand-off back on. If TripPlanner cannot read the settings, it uses this default.", "raise": "On: the AA planner never collects traveller contacts; agencies are unaffected.", "lower": "Off: the AA planner collects traveller contacts and creates enquiries and Booking cases again.", "when": "Keep it on while AA sells only to agencies; turn it off only if AA decides to take travellers directly again.", "example": "With the default on: a traveller on the AA demo who presses 'send to advisor' sees the agencies-only message."}, "vi": {"what": "Bật (chỉ phục vụ doanh nghiệp): trên planner trần và bản demo của AA, 'gửi cho tư vấn viên' trả lời rằng dịch vụ dành cho đại lý và không lưu gì (không đăng ký, không yêu cầu, không tạo hồ sơ Booking). Planner của đại lý vẫn gửi lead cho đại lý đó trong cả hai trường hợp. Tắt sẽ bật lại luồng chuyển khách cũ của AA. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị mặc định này.", "raise": "Bật: planner của AA không bao giờ thu thông tin liên hệ của khách; đại lý không bị ảnh hưởng.", "lower": "Tắt: planner của AA lại thu thông tin liên hệ của khách, tạo yêu cầu và hồ sơ Booking.", "when": "Giữ bật khi AA chỉ bán cho đại lý; chỉ tắt nếu AA quyết định nhận khách trực tiếp trở lại.", "example": "Với mặc định on: khách trên bản demo của AA bấm 'gửi cho tư vấn viên' sẽ thấy thông báo chỉ dành cho đại lý."}}},
{"key": "tripplanner.handoff.require_registration", "description": "On: the frozen AA hand-off (advisor demo off) needs the traveller's name and a phone or e-mail before it sends. Fallback while TripPlanner cannot read the view: this default.", "guide": {"en": {"what": "On: the old AA hand-off (used only when 'Send to advisor on the AA planner is a demo' is off) asks for the traveller's name and a phone or e-mail before sending. If TripPlanner cannot read the settings, it uses this default.", "raise": "On: every hand-off carries contact details the team can follow up.", "lower": "Off: travellers can send without details; more hand-offs, many without a way to reply.", "when": "Matters only with the demo switch off; turn it off only to test the flow.", "example": "With the default on: a traveller must enter a name and a phone or e-mail first."}, "vi": {"what": "Bật: luồng chuyển khách cũ của AA (chỉ dùng khi tắt thiết lập 'gửi cho tư vấn viên trên planner AA là bản demo') yêu cầu tên và số điện thoại hoặc e-mail của khách trước khi gửi. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị mặc định này.", "raise": "Bật: mọi lần chuyển khách đều có thông tin liên hệ để đội ngũ liên lạc lại.", "lower": "Tắt: khách gửi được mà không cần thông tin; nhiều lượt chuyển hơn, nhiều lượt không có cách liên lạc.", "when": "Chỉ có tác dụng khi tắt công tắc demo; chỉ tắt để thử luồng.", "example": "Với mặc định on: khách phải nhập tên và số điện thoại hoặc e-mail trước."}}},
{"key": "tripplanner.leads.hold_days", "description": "Days TripPlanner keeps an undelivered lead before it is redacted anyway (data standards DM-7.1 row tripplanner.outbox: at most 7 days). The floor 3 keeps two daily expiry ticks of headroom inside the hold. Fallback while TripPlanner cannot read the view: this default.", "guide": {"en": {"what": "How many days TripPlanner keeps a lead it could not deliver to the agency before it removes the traveller's details anyway. Data rules allow at most 7 days; the minimum of 3 keeps two daily clean-up runs of margin. If TripPlanner cannot read the settings, it uses this default.", "raise": "Delivery has longer to recover from an outage before the lead is lost; personal data is kept longer (never over 7 days).", "lower": "Personal data is removed sooner; a longer outage loses more leads.", "when": "Lower it if the privacy review asks for shorter keeping; keep it high while lead delivery is unstable.", "example": "With the default of 7 days: an undelivered lead loses its contact details on day 7."}, "vi": {"what": "TripPlanner giữ lead chưa giao được cho đại lý bao nhiêu ngày trước khi vẫn xoá thông tin cá nhân của khách. Quy định dữ liệu cho phép tối đa 7 ngày; mức tối thiểu 3 chừa khoảng cho hai lần dọn dẹp hằng ngày. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị mặc định này.", "raise": "Việc giao lead có thêm thời gian phục hồi sau sự cố trước khi mất lead; dữ liệu cá nhân được giữ lâu hơn (không quá 7 ngày).", "lower": "Dữ liệu cá nhân được xoá sớm hơn; sự cố kéo dài làm mất nhiều lead hơn.", "when": "Giảm nếu đánh giá quyền riêng tư yêu cầu giữ ngắn hơn; để cao khi việc giao lead chưa ổn định.", "example": "Với mặc định 7 ngày: lead chưa giao bị xoá thông tin liên hệ vào ngày thứ 7."}}},
{"key": "tripplanner.leads.tenant_daily_cap", "description": "Leads one agency tenant may receive in 24 hours. Past it a send is refused before anything is stored (429 lead_cap_reached), so a script on a public planner cannot flood the agency's inbox or CRM. A tenant value overrides the platform value for that tenant. Fallback while TripPlanner cannot read the view: this default.", "guide": {"en": {"what": "How many leads one agency may receive in 24 hours. Past it a 'send to advisor' is refused before anything is stored, so a script on a public planner cannot flood the agency's inbox or CRM. A value set for one agency overrides this platform value. If TripPlanner cannot read the settings, it uses this default.", "raise": "A busy agency is not cut off; a flood of fake leads can grow larger before it stops.", "lower": "Floods stop sooner; a very busy agency may lose real leads at the end of a day.", "when": "Raise it for an agency that really gets this many enquiries (per agency); lower it after a lead flood.", "example": "With the default of 200: the 201st lead of an agency within 24 hours is refused."}, "vi": {"what": "Một đại lý được nhận tối đa bao nhiêu lead trong 24 giờ. Vượt mức thì yêu cầu 'gửi cho tư vấn viên' bị từ chối trước khi lưu gì, để một script trên planner công khai không làm ngập hộp thư hay CRM của đại lý. Giá trị đặt riêng cho một đại lý sẽ thay giá trị chung này. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị mặc định này.", "raise": "Đại lý đông khách không bị cắt; đợt lead giả có thể lớn hơn trước khi bị chặn.", "lower": "Đợt lead giả bị chặn sớm hơn; đại lý rất đông khách có thể mất lead thật cuối ngày.", "when": "Tăng cho đại lý thật sự nhận nhiều yêu cầu như vậy (đặt riêng); giảm sau một đợt lead giả.", "example": "Với mặc định 200: lead thứ 201 của một đại lý trong 24 giờ bị từ chối."}}},
{"key": "tripplanner.rate.chat_ip_per_hour", "description": "Planning chat messages one traveller IP may send in one hour, counted only when the message would reach a model. Fallback while TripPlanner cannot read the view: this default.", "guide": {"en": {"what": "How many planning chat messages one traveller IP address may send in an hour, counting only messages that reach a model. It catches one machine opening many sessions. Past it the planner answers 'too many requests' and asks them to wait. If TripPlanner cannot read the settings, it uses this default.", "raise": "Heavy users are stopped less often; a script can run up more paid calls before it is stopped.", "lower": "Paid calls are better protected from abuse; a busy real traveller may hit the limit.", "when": "Raise it when real travellers report 'too many requests'; lower it when the AI call log shows one visitor running up cost.", "example": "With the default of 40: the 41st message in an hour is refused."}, "vi": {"what": "Số tin nhắn trò chuyện lập kế hoạch một địa chỉ IP của khách được gửi mỗi giờ, chỉ tính tin có tới model. Nó chặn trường hợp một máy mở nhiều phiên. Vượt mức thì planner báo 'quá nhiều yêu cầu' và đề nghị chờ. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị mặc định này.", "raise": "Người dùng nhiều ít bị chặn hơn; một script có thể gây thêm nhiều lượt gọi có phí trước khi bị chặn.", "lower": "Lượt gọi có phí được bảo vệ tốt hơn khỏi lạm dụng; khách thật dùng nhiều có thể chạm giới hạn.", "when": "Tăng khi khách thật báo 'quá nhiều yêu cầu'; giảm khi nhật ký gọi AI cho thấy một khách gây tốn kém.", "example": "Với mặc định 40: tin nhắn thứ 41 trong cùng một giờ bị từ chối."}}},
{"key": "tripplanner.rate.chat_per_hour", "description": "Planning chat messages one guest session may send in one hour, counted only when the message would reach a model. Fallback while TripPlanner cannot read the view: this default.", "guide": {"en": {"what": "How many planning chat messages one guest session may send in an hour, counting only messages that reach a model. A signed-in traveller gets the signed-in factor times this. Past it the planner answers 'too many requests' and asks them to wait. If TripPlanner cannot read the settings, it uses this default.", "raise": "Heavy users are stopped less often; a script can run up more paid calls before it is stopped.", "lower": "Paid calls are better protected from abuse; a busy real traveller may hit the limit.", "when": "Raise it when real travellers report 'too many requests'; lower it when the AI call log shows one visitor running up cost.", "example": "With the default of 20: the 21st message in an hour is refused."}, "vi": {"what": "Số tin nhắn trò chuyện lập kế hoạch một phiên khách được gửi mỗi giờ, chỉ tính tin có tới model. Khách đã đăng nhập được nhân thêm theo hệ số đăng nhập. Vượt mức thì planner báo 'quá nhiều yêu cầu' và đề nghị chờ. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị mặc định này.", "raise": "Người dùng nhiều ít bị chặn hơn; một script có thể gây thêm nhiều lượt gọi có phí trước khi bị chặn.", "lower": "Lượt gọi có phí được bảo vệ tốt hơn khỏi lạm dụng; khách thật dùng nhiều có thể chạm giới hạn.", "when": "Tăng khi khách thật báo 'quá nhiều yêu cầu'; giảm khi nhật ký gọi AI cho thấy một khách gây tốn kém.", "example": "Với mặc định 20: tin nhắn thứ 21 trong cùng một giờ bị từ chối."}}},
{"key": "tripplanner.rate.narrate_per_hour", "description": "Narrations one guest session may ask for in one hour when the request would call a model (a cached or all-AA-text narration is not counted). A signed-in traveller gets the signed-in factor times this. Past it the planner answers 429 and shows the basic narration. Fallback while TripPlanner cannot read the view: this default.", "guide": {"en": {"what": "How many AI trip stories (the narration of a planned trip) one guest session may ask for in an hour, counting only requests that call a model (a cached story is free and not counted). A signed-in traveller gets the signed-in factor times this. Past it the planner answers 'too many requests' and asks them to wait. If TripPlanner cannot read the settings, it uses this default.", "raise": "Heavy users are stopped less often; a script can run up more paid calls before it is stopped.", "lower": "Paid calls are better protected from abuse; a busy real traveller may hit the limit.", "when": "Raise it when real travellers report 'too many requests'; lower it when the AI call log shows one visitor running up cost.", "example": "With the default of 10: the 11th story in an hour is refused."}, "vi": {"what": "Số câu chuyện chuyến đi bằng AI (lời kể cho lịch trình đã lập) một phiên khách được yêu cầu mỗi giờ, chỉ tính các yêu cầu có gọi model (câu chuyện đã lưu sẵn thì miễn phí, không tính). Khách đã đăng nhập được nhân thêm theo hệ số đăng nhập. Vượt mức thì planner báo 'quá nhiều yêu cầu' và đề nghị chờ. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị mặc định này.", "raise": "Người dùng nhiều ít bị chặn hơn; một script có thể gây thêm nhiều lượt gọi có phí trước khi bị chặn.", "lower": "Lượt gọi có phí được bảo vệ tốt hơn khỏi lạm dụng; khách thật dùng nhiều có thể chạm giới hạn.", "when": "Tăng khi khách thật báo 'quá nhiều yêu cầu'; giảm khi nhật ký gọi AI cho thấy một khách gây tốn kém.", "example": "Với mặc định 10: câu chuyện thứ 11 trong cùng một giờ bị từ chối."}}},
{"key": "tripplanner.rate.search_per_minute", "description": "Free-text searches one traveller IP may run in one minute when the query would call the embedding model (an empty query is not counted). A signed-in traveller gets the signed-in factor times this. Past it search answers 429. Fallback while TripPlanner cannot read the view: this default.", "guide": {"en": {"what": "How many free-text searches one traveller IP address may run in a minute, counting only searches that call the AI search model (an empty search is not counted). A signed-in traveller gets the signed-in factor times this. Past it the planner answers 'too many requests' and asks them to wait. If TripPlanner cannot read the settings, it uses this default.", "raise": "Heavy users are stopped less often; a script can run up more paid calls before it is stopped.", "lower": "Paid calls are better protected from abuse; a busy real traveller may hit the limit.", "when": "Raise it when real travellers report 'too many requests'; lower it when the AI call log shows one visitor running up cost.", "example": "With the default of 30: the 31st search in a minute is refused."}, "vi": {"what": "Số lượt tìm kiếm tự do một địa chỉ IP của khách được chạy mỗi phút, chỉ tính các lượt có gọi model tìm kiếm AI (ô tìm kiếm trống không tính). Khách đã đăng nhập được nhân thêm theo hệ số đăng nhập. Vượt mức thì planner báo 'quá nhiều yêu cầu' và đề nghị chờ. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị mặc định này.", "raise": "Người dùng nhiều ít bị chặn hơn; một script có thể gây thêm nhiều lượt gọi có phí trước khi bị chặn.", "lower": "Lượt gọi có phí được bảo vệ tốt hơn khỏi lạm dụng; khách thật dùng nhiều có thể chạm giới hạn.", "when": "Tăng khi khách thật báo 'quá nhiều yêu cầu'; giảm khi nhật ký gọi AI cho thấy một khách gây tốn kém.", "example": "Với mặc định 30: lượt tìm thứ 31 trong cùng một phút bị từ chối."}}},
{"key": "tripplanner.rate.send_ip_per_hour", "description": "Send to advisor requests one traveller IP may make in one hour on an agency tenant's planner, counted only when the request would store a lead. Fallback while TripPlanner cannot read the view: this default.", "guide": {"en": {"what": "How many 'send to advisor' requests one traveller IP address may make in an hour on an agency's planner, counting only requests that store a lead. It catches one machine opening many sessions. Past it the planner answers 'too many requests' and asks them to wait. If TripPlanner cannot read the settings, it uses this default.", "raise": "Several travellers on one network (a hotel, an office) can send more leads; a script on one machine can push more fake leads with contact details into the agency's inbox and CRM before it is stopped.", "lower": "Fake-lead floods from one machine stop sooner; travellers who share a network may be refused.", "when": "Lower it when agencies report spam leads; raise it when real travellers report 'too many requests' when they send to an advisor.", "example": "With the default of 20: the 21st lead in an hour is refused."}, "vi": {"what": "Số yêu cầu 'gửi cho tư vấn viên' một địa chỉ IP của khách được gửi mỗi giờ trên planner của đại lý, chỉ tính các yêu cầu có lưu lead. Nó chặn trường hợp một máy mở nhiều phiên. Vượt mức thì planner báo 'quá nhiều yêu cầu' và đề nghị chờ. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị mặc định này.", "raise": "Nhiều khách dùng chung một mạng (khách sạn, văn phòng) gửi được nhiều lead hơn; một script trên một máy có thể đẩy thêm nhiều lead giả kèm thông tin liên hệ vào hộp thư và CRM của đại lý trước khi bị chặn.", "lower": "Đợt lead giả từ một máy bị chặn sớm hơn; khách dùng chung một mạng có thể bị từ chối.", "when": "Giảm khi đại lý báo nhận lead rác; tăng khi khách thật báo 'quá nhiều yêu cầu' lúc gửi cho tư vấn viên.", "example": "Với mặc định 20: lead thứ 21 trong cùng một giờ bị từ chối."}}},
{"key": "tripplanner.rate.send_per_hour", "description": "Send to advisor requests one guest session may make in one hour on an agency tenant's planner, counted only when the request would store a lead (it carries the traveller's contact). Fallback while TripPlanner cannot read the view: this default.", "guide": {"en": {"what": "How many 'send to advisor' requests (a lead with the traveller's contact) one guest session may make in an hour on an agency's planner, counting only requests that store a lead. A signed-in traveller gets the signed-in factor times this. Past it the planner answers 'too many requests' and asks them to wait. If TripPlanner cannot read the settings, it uses this default.", "raise": "A real traveller can resend more often; a script can push more fake leads with contact details into the agency's inbox and CRM before it is stopped.", "lower": "Fake-lead floods stop sooner; a traveller who retries several times may be refused.", "when": "Lower it when agencies report spam leads; raise it when real travellers report 'too many requests' when they send to an advisor.", "example": "With the default of 5: the 6th lead in an hour is refused."}, "vi": {"what": "Số yêu cầu 'gửi cho tư vấn viên' (một lead kèm thông tin liên hệ của khách) một phiên khách được gửi mỗi giờ trên planner của đại lý, chỉ tính các yêu cầu có lưu lead. Khách đã đăng nhập được nhân thêm theo hệ số đăng nhập. Vượt mức thì planner báo 'quá nhiều yêu cầu' và đề nghị chờ. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị mặc định này.", "raise": "Khách thật được gửi lại nhiều lần hơn; một script có thể đẩy thêm nhiều lead giả kèm thông tin liên hệ vào hộp thư và CRM của đại lý trước khi bị chặn.", "lower": "Đợt lead giả bị chặn sớm hơn; khách gửi lại vài lần có thể bị từ chối.", "when": "Giảm khi đại lý báo nhận lead rác; tăng khi khách thật báo 'quá nhiều yêu cầu' lúc gửi cho tư vấn viên.", "example": "Với mặc định 5: lead thứ 6 trong cùng một giờ bị từ chối."}}},
{"key": "tripplanner.rate.signed_in_factor", "description": "A signed-in traveller gets this many times every per-session and per-IP allowance (narration, search, send to advisor, planning chat). 1 = no extra allowance. Fallback while TripPlanner cannot read the view: this default.", "guide": {"en": {"what": "A signed-in traveller gets this many times every per-session and per-IP allowance (trip stories, search, send to advisor, planning chat). 1 = no extra allowance. If TripPlanner cannot read the settings, it uses this default.", "raise": "Signed-in travellers can use the planner more before they hit a limit; an abused account can cost more.", "lower": "Signed-in travellers are limited like guests.", "when": "Raise it when signed-in travellers report 'too many requests'; lower it if accounts are created to get around the limits.", "example": "With the default of 2: a signed-in traveller may ask for 20 AI trip stories an hour where a guest gets 10."}, "vi": {"what": "Khách đã đăng nhập được gấp bao nhiêu lần mọi hạn mức theo phiên và theo IP (câu chuyện chuyến đi, tìm kiếm, gửi cho tư vấn viên, trò chuyện lập kế hoạch). 1 = không thêm. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị mặc định này.", "raise": "Khách đăng nhập dùng planner được nhiều hơn trước khi chạm giới hạn; tài khoản bị lạm dụng có thể gây tốn hơn.", "lower": "Khách đăng nhập bị giới hạn như khách vãng lai.", "when": "Tăng khi khách đăng nhập báo 'quá nhiều yêu cầu'; giảm nếu có người tạo tài khoản để lách giới hạn.", "example": "Với mặc định 2: khách đăng nhập được 20 câu chuyện chuyến đi mỗi giờ, khách vãng lai được 10."}}},
{"key": "tripplanner.spend.plan_chat_monthly_cap_usd", "description": "The planning chat's model spend of the whole app per UTC month (tripplanner.ai_spend_month). At the cap the chat pauses with a plain message; the rest of the planner is untouched. The daily app cap (AI gateway > App profiles) and an agency tenant's AI budget apply too. Fallback while TripPlanner cannot read the view: this default.", "guide": {"en": {"what": "The most the planning chat of the whole TripPlanner app may spend on AI calls in one calendar month (UTC). At the cap the chat pauses with a plain message; the rest of the planner keeps working. The app's daily cap (AI gateway > App profiles) and each agency's AI budget apply too. If TripPlanner cannot read the settings, it uses this default.", "raise": "The chat stays open longer in a busy month; the month can cost more.", "lower": "The chat pauses sooner in a busy month.", "when": "Raise it when the chat pauses before month end and its use is real; lower it when spend grows without bookings or leads to show for it.", "example": "With the default of 2 USD a month: the chat pauses for the rest of the month once 2 USD is spent."}, "vi": {"what": "Số tiền tối đa phần trò chuyện lập kế hoạch của cả ứng dụng TripPlanner được chi cho lượt gọi AI trong một tháng (theo UTC). Chạm mức thì trò chuyện tạm dừng với một thông báo đơn giản; phần còn lại của planner vẫn chạy. Mức trần theo ngày của ứng dụng (AI gateway > App profiles) và ngân sách AI của từng đại lý cũng áp dụng. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị mặc định này.", "raise": "Trò chuyện mở lâu hơn trong tháng đông khách; tháng đó có thể tốn hơn.", "lower": "Trò chuyện tạm dừng sớm hơn trong tháng đông khách.", "when": "Tăng khi trò chuyện dừng trước cuối tháng mà nhu cầu là thật; giảm khi chi phí tăng mà không có booking hay lead tương ứng.", "example": "Với mặc định 2 USD mỗi tháng: chi đủ 2 USD thì trò chuyện dừng tới hết tháng."}}},
{"key": "tripplanner.spend.plan_chat_tenant_monthly_cap_usd", "description": "The planning chat's model spend of one tenant per UTC month (the AA demo tenant included). The platform value applies to every tenant; a tenant value overrides it for that tenant. Fallback while TripPlanner cannot read the view: this default.", "guide": {"en": {"what": "The most the planning chat may spend on AI calls for one agency in one calendar month (UTC), the AA demo included. A value set for one agency overrides this platform value for that agency. If TripPlanner cannot read the settings, it uses this default.", "raise": "Each agency's travellers can chat more in a month; one busy agency can cost more.", "lower": "Each agency's chat pauses sooner; the cost of one agency is better bounded.", "when": "Raise it for agencies whose travellers really use the chat (per agency, on the tenant row); lower it if one agency's chat costs more than it brings.", "example": "With the default of 2 USD a month: an agency's chat pauses for the month after 2 USD of its own spend."}, "vi": {"what": "Số tiền tối đa phần trò chuyện lập kế hoạch được chi cho lượt gọi AI của một đại lý trong một tháng (theo UTC), kể cả bản demo của AA. Giá trị đặt riêng cho một đại lý sẽ thay giá trị chung này cho đại lý đó. Nếu TripPlanner không đọc được thiết lập, nó dùng giá trị mặc định này.", "raise": "Khách của mỗi đại lý trò chuyện được nhiều hơn mỗi tháng; một đại lý đông khách có thể tốn hơn.", "lower": "Trò chuyện của mỗi đại lý dừng sớm hơn; chi phí của một đại lý được giới hạn chặt hơn.", "when": "Tăng cho đại lý có khách thật sự dùng trò chuyện (đặt riêng trên dòng của đại lý); giảm nếu trò chuyện của một đại lý tốn hơn giá trị mang lại.", "example": "Với mặc định 2 USD mỗi tháng: trò chuyện của đại lý dừng tới hết tháng khi đại lý đó đã chi 2 USD."}}}
]$edit$::jsonb) AS e (doc)
ON CONFLICT (key) DO UPDATE SET doc = EXCLUDED.doc;
-- settings-edit:end

UPDATE shared.setting_definition AS d
   SET env_override = CASE WHEN e.doc ? 'env_override' THEN e.doc ->> 'env_override' ELSE d.env_override END,
       description  = COALESCE(e.doc ->> 'description', d.description),
       guide        = CASE WHEN e.doc ? 'guide' THEN e.doc -> 'guide' ELSE d.guide END
  FROM m428_edit AS e
 WHERE d.key = e.key
   AND (d.env_override IS DISTINCT FROM CASE WHEN e.doc ? 'env_override' THEN e.doc ->> 'env_override'
                                             ELSE d.env_override END
        OR d.description IS DISTINCT FROM COALESCE(e.doc ->> 'description', d.description)
        OR d.guide IS DISTINCT FROM CASE WHEN e.doc ? 'guide' THEN e.doc -> 'guide' ELSE d.guide END);

-- Post-check: every row of the block exists with its new fields (a misspelt key would leave an override in place
-- without an error), and no definition names an env var any more.
DO $check$
DECLARE
    missing text;
    still text;
BEGIN
    SELECT string_agg(e.key, ', ' ORDER BY e.key) INTO missing
      FROM m428_edit AS e
     WHERE NOT EXISTS (
           SELECT 1 FROM shared.setting_definition AS d
            WHERE d.key = e.key
              AND (NOT e.doc ? 'env_override' OR d.env_override IS NULL)
              AND (NOT e.doc ? 'description' OR d.description = e.doc ->> 'description')
              AND (NOT e.doc ? 'guide' OR d.guide = e.doc -> 'guide'));
    IF missing IS NOT NULL THEN
        RAISE EXCEPTION 'CIS 424: no definition or not edited: %', missing;
    END IF;
    SELECT string_agg(d.key || ' (' || d.env_override || ')', ', ' ORDER BY d.key) INTO still
      FROM shared.setting_definition AS d
     WHERE d.env_override IS NOT NULL;
    IF still IS NOT NULL THEN
        RAISE EXCEPTION 'CIS 424: definitions still name an env override: %', still;
    END IF;
END
$check$;

INSERT INTO shared.schema_versions (version, applied_at, description)
VALUES ('424', now(), 'AA-1096 l5: retire the one-release env overrides of the platform settings registry')
ON CONFLICT (version) DO NOTHING;

COMMIT;
